<?php
$title='Application status'; require 'header.php'; $ref=trim($_GET['ref']??''); $candidate=null; $events=[];
if($ref){$st=db()->prepare("SELECT c.*,j.title job_title FROM candidates c JOIN jobs j ON j.id=c.job_id WHERE c.application_no=?");$st->bind_param('s',$ref);$st->execute();$candidate=stmt_one($st); if($candidate){$ev=db()->prepare("SELECT * FROM candidate_events WHERE candidate_id=? ORDER BY created_at DESC");$ev->bind_param('i',$candidate['id']);$ev->execute();$events=stmt_rows($ev);}}
?>
<main class="container status-page"><div class="form-intro"><span class="eyebrow">CANDIDATE PORTAL</span><h1>Track your application</h1><p>Enter the application number you received after submitting.</p></div><form class="track-form" method="get"><input name="ref" value="<?=e($ref)?>" placeholder="HF-XXXXXXXX" required><button class="btn dark">Check status</button></form>
<?php if($ref && !$candidate): ?><div class="notice">We couldn't find that application number.</div><?php elseif($candidate): ?><section class="status-card"><div><span class="role-dept"><?=e($candidate['job_title'])?></span><h2><?=e($candidate['first_name'].' '.$candidate['last_name'])?></h2><p><?=e($candidate['email'])?></p></div><div class="big-status <?=e($candidate['status'])?>"><?=e(status_label($candidate['status']))?></div></section><div class="timeline"><?php foreach($events as $ev): ?><div class="timeline-item"><span></span><div><strong><?=e($ev['event_text'])?></strong><small><?=e(date('M j, Y · g:i A',strtotime($ev['created_at'])))?></small></div></div><?php endforeach; ?></div><?php endif; ?></main><?php require 'footer.php'; ?>